// Text attachments generated by the assistant. Binary files require a real
// conversion backend, so they are intentionally not advertised here.
export type GeneratedFile = { name: string; content: string; mime: string };

const MIME: Record<string, string> = {
  txt: "text/plain", md: "text/markdown", html: "text/html", htm: "text/html",
  css: "text/css", js: "text/javascript", jsx: "text/javascript", ts: "text/plain",
  tsx: "text/plain", json: "application/json", csv: "text/csv", py: "text/x-python",
  xml: "application/xml", svg: "image/svg+xml", sql: "text/plain",
  yaml: "text/yaml", yml: "text/yaml", sh: "text/plain", log: "text/plain",
};

export function extractGeneratedFiles(answer: string): { text: string; files: GeneratedFile[] } {
  const files: GeneratedFile[] = [];
  let total = 0;
  const text = answer.replace(/<kapani_file\s+name=["']([^"']{1,120})["']\s*>([\s\S]*?)<\/kapani_file>/gi, (full, rawName: string, content: string) => {
    const name = rawName.replace(/\\/g, "/").split("/").pop()?.replace(/[^\p{L}\p{N}_.()\- ]/gu, "_").replace(/^\.+/, "") || "";
    const extension = name.split(".").pop()?.toLowerCase() || "";
    if (!name || !Object.hasOwn(MIME, extension) || files.length >= 4 || content.length > 60000 || total + content.length > 140000)
      return full;
    total += content.length;
    files.push({ name, content: content.replace(/^\n/, "").replace(/\n$/, ""), mime: MIME[extension] });
    return "";
  }).replace(/\n{3,}/g, "\n\n").trim();
  return { text: text || (files.length ? "Готово, файлы прикреплены ниже." : answer), files };
}
